import {calendarIndex,eventRule,adjustedRisk,addDays} from './model.mjs';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const iconPaths={sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.4 1.4m11.2 11.2L19 19M5 19l1.4-1.4M17.6 6.4 19 5"/>',globe:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c5 5 5 13 0 18-5-5-5-13 0-18Z"/>',book:'<path d="M12 5c-3-2-6-2-9-1v15c3-1 6-1 9 1 3-2 6-2 9-1V4c-3-1-6-1-9 1Zm0 0v15"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v.2"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',history:'<path d="M4 6v5h5M4.5 8A8 8 0 1 1 4 16m8-10v6l4 2"/>',layers:'<path d="m12 3 9 5-9 5-9-5 9-5Zm-9 9 9 5 9-5M3 16l9 5 9-5"/>',pin:'<path d="M20 10c0 6-8 11-8 11S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18"/>',thermometer:'<path d="M9 14.5V5a3 3 0 0 1 6 0v9.5a5 5 0 1 1-6 0ZM12 8v9"/><circle cx="12" cy="18" r="1"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 17v4h16v-4"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',activity:'<path d="M2 12h5l3-8 4 16 3-8h5"/>',file:'<path d="M14 2H5v20h14V7l-5-5Zm0 0v5h5M8 12h8m-8 4h6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',check:'<path d="m5 12 4 4 10-10"/>',alert:'<path d="m12 3 10 18H2L12 3Zm0 6v5m0 3v.2"/>','arrow-up-right':'<path d="M6 18 18 6M6 6h12v12"/>','arrow-right':'<path d="M4 12h16m-6-6 6 6-6 6"/>'};
const icon=name=>`<i data-icon="${name}"><svg viewBox="0 0 24 24" aria-hidden="true">${iconPaths[name]||iconPaths.info}</svg></i>`;
function hydrateIcons(root=document){root.querySelectorAll('i[data-icon]').forEach(i=>{if(!i.firstElementChild)i.innerHTML=`<svg viewBox="0 0 24 24" aria-hidden="true">${iconPaths[i.dataset.icon]||iconPaths.info}</svg>`;});}
hydrateIcons();
const state={source:'issued',view:'explorer',site:0,date:'2026-08-12',lead:1,task:'ongoing',lines:new Set(['observed','forecast','threshold']),window:21,metric:'f1',atlasMethod:'joint_error_adjusted',live:null,notice:'',perSourceDates:{}};
let datasets={},manifest,geo,liveModel,chartRows=[],chartLayout={},hoverIndex=null,toastTimer,liveRequest=null;
const fmtDate=(d,options={day:'numeric',month:'short',year:'numeric'})=>new Date(d.slice(0,10)+'T12:00:00Z').toLocaleDateString('en-GB',{...options,timeZone:'UTC'});
const n=(v,d=2)=>Number.isFinite(v)?Number(v).toFixed(d):'—';
const pct=v=>Number.isFinite(v)?`${Math.round(v*100)}%`:'—';
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const expName=()=>`${state.task}_lead${state.lead}`;
const data=()=>datasets[state.source==='live'?'issued':state.source];
const experiment=()=>data().experiments[expName()];
function showToast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,4500);}
function dialog(eyebrow,title,html){$('#dialog-eyebrow').textContent=eyebrow;$('#dialog-title').textContent=title;$('#dialog-content').innerHTML=html;$('#detail-dialog').showModal();hydrateIcons($('#detail-dialog'));}
function selectedRecord(){if(state.source==='live')return liveRecord();const e=experiment();const i=e.dates.indexOf(state.date);if(i<0)throw Error('This date is not in the saved held-out prediction set.');const s=state.site;return {probability:e.probabilities[i][s],predicted:e.predicted[i][s],truth:e.truth[i][s],cutoff:e.cutoff,raw:e.raw?.[i]?.[s],issue:e.issueTimes[i],initialization:e.initializations?.[i],allProbabilities:e.probabilities[i],index:i};}
function validDates(){return state.source==='live'?[addDays(new Date().toISOString().slice(0,10),state.lead)]:experiment().dates;}
function setDate(date){const dates=validDates();if(!dates.includes(date)){const nearest=dates.reduce((best,d)=>Math.abs(Date.parse(d)-Date.parse(date))<Math.abs(Date.parse(best)-Date.parse(date))?d:best,dates[0]);state.notice=`No held-out record exists for ${fmtDate(date)} in this experiment. Showing the nearest available date: ${fmtDate(nearest)}.`;date=nearest;}else state.notice='';state.date=date;render();}
function syncURL(){const p=new URLSearchParams({source:state.source,site:manifest.sites[state.site].id,date:state.date,lead:state.lead,event:state.task});history.replaceState(null,'',`${location.pathname}?${p}#${state.view}`);}
function setView(view){state.view=view;$('#sidebar').classList.remove('open');$('#menu-button').setAttribute('aria-expanded','false');render();window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}
async function setSource(source){if(source===state.source)return;state.perSourceDates[state.source]=state.date;state.source=source;state.notice='';if(source==='live'){state.date=validDates()[0];renderControls();await loadLive();}else{const dates=validDates();state.date=state.perSourceDates[source]|| (source==='issued'?'2026-08-12':'2025-08-12');if(!dates.includes(state.date))state.date=dates[dates.length-1];render();}}
function renderControls(){$('#export-button').innerHTML=icon('download')+(state.view==='research'?'Download paper':state.view==='atlas'?'Export metrics':'Export forecast');document.body.dataset.source=state.source;document.body.dataset.view=state.view;$('#location').value=String(state.site);$('#event-type').value=state.task;$$('.source-tab[data-source]').forEach(b=>{const active=b.dataset.source===state.source;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});$$('[data-lead]').forEach(b=>{const active=Number(b.dataset.lead)===state.lead;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});$$('.nav-item[data-view]').forEach(b=>{const active=b.dataset.view===state.view;b.classList.toggle('active',active);active?b.setAttribute('aria-current','page'):b.removeAttribute('aria-current');});const dates=validDates();const input=$('#target-date');input.min=dates[0];input.max=dates[dates.length-1];input.value=state.date;input.readOnly=state.source==='live';const index=dates.indexOf(state.date);$('#previous-day').disabled=index<=0||state.source==='live';$('#next-day').disabled=index>=dates.length-1||state.source==='live';const title={explorer:['LESS UNCERTAINTY. MORE PERSPECTIVE.','Heat, in <em>perspective.</em>','Follow the signals. Explore what the models predicted, and what happened next.'],atlas:['LOOK BEYOND THE AVERAGE.','The shape of <em>forecast skill.</em>','See where the model performs well, and where the evidence is more limited.'],research:['A FORECAST SHOULD BE EXPLAINABLE.','Evidence, made <em>visible.</em>','The data, decisions, and limits behind this observatory.']}[state.view];$('#page-eyebrow').textContent=title[0];$('#page-title').innerHTML=title[1];$('#page-description').textContent=title[2];$('#breadcrumb-current').textContent={explorer:'FORECAST EXPLORER',atlas:'REGIONAL ATLAS',research:'THE RESEARCH'}[state.view];$('#source-info span').textContent=state.source==='live'?'Live provider feed':state.source==='issued'?'Historical replay':'Historical experiment';$('#notice').hidden=!state.notice;$('#notice').textContent=state.notice;}
function render(){if(!manifest)return;renderControls();if(state.source==='live'&&!state.live)return;$('#loading').hidden=true;$('#error-state').hidden=true;$$('.view').forEach(v=>v.hidden=v.id!==`${state.view}-view`);if(state.view==='explorer')renderExplorer();if(state.view==='atlas')renderAtlas();hydrateIcons();syncURL();}
function renderExplorer(){const r=selectedRecord(),site=manifest.sites[state.site],isLive=state.source==='live';const p=r.probability;const outside=isLive&&!r.validatedSeason;$('.forecast-card').classList.toggle('outside',outside);$('#location-country').textContent=site.country.toUpperCase();$('#location-heading').innerHTML=`${escape(site.name)}<span class="small-arrow">↗</span>`;$('#date-stamp').textContent=fmtDate(state.date);$('#probability-number').textContent=Number.isFinite(p)?Math.round(p*100):'—';$('#probability-unit').textContent=Number.isFinite(p)?'%':'';$('#probability-label').textContent=isLive?(outside?'Outside the validated summer period':'Experimental live event probability'):state.source==='research'?'Saved gradient-boosting probability':'Adjusted event probability';$('#ring-fill').style.strokeDashoffset=270.176*(1-(p||0));$('#ring-icon').innerHTML=`<g transform="translate(39,39) scale(1.33)">${iconPaths.sun}</g>`;$('#prediction-status').innerHTML=icon(outside?'info':r.predicted?'thermometer':'check')+`<span>${outside?'Temperature outlook only':r.predicted?'Event signal detected':'No event signal at this cutoff'}</span>`;$('#prediction-explanation').textContent=outside?'The model was evaluated for May–September. Live temperatures are shown; a heatwave probability is not published for this season.':`${r.predicted?'Above':'Below'} the study’s ${pct(r.cutoff)} classification cutoff. ${state.task==='onset'?'Target: the first day of a new three-day hot spell.':'Target: the third or later consecutive hot day.'}`;$('#observed-label').textContent=isLive?'VERIFICATION STATUS':'OBSERVED AFTERWARD';$('#observed-outcome').textContent=isLive?'Future outcome not yet observed':r.truth?(state.task==='onset'?'New event confirmed in ERA5':'Heatwave day confirmed in ERA5'):(state.task==='onset'?'No event onset in ERA5':'No ongoing event in ERA5');$('#observed-icon').innerHTML=icon(isLive?'clock':r.truth?'thermometer':'check');const match=r.predicted===r.truth;$('#outcome-pill').textContent=isLive?'Not verified':match?(r.truth?'Event hit':'Correct negative'):(r.truth?'Missed event':'False alert');$('#outcome-pill').classList.toggle('miss',!isLive&&!match);$('#model-label').textContent=isLive?'Latest GFS feed · experimental adjustment':state.source==='issued'?'Archived GFS + joint-error adjustment':'Saved gradient-boosting model output';$('#scenario-badge').textContent=isLive?'LIVE FEED · UNVERIFIED':state.source==='issued'?'ARCHIVED FORECAST · VERIFIED AFTERWARD':'SAVED MODEL OUTPUT · VERIFIED AFTERWARD';$('#scenario-label').textContent=isLive?'YOUR LIVE WEATHER OUTLOOK':'YOUR FORECAST AT A GLANCE';$('#chart-title').textContent=isLive?'The days ahead.':'Before, during, and after.';$('#chart-description').textContent=isLive?'Latest provider temperatures against the fixed local climate threshold.':'Compare the forecast or model context with temperatures verified afterward.';$('#bottom-note').textContent=isLive?'Live estimates are experimental. The latest provider feed differs from the frozen-run benchmark.':'Historical observations were collected after the event; they are verification, not future predictor inputs.';renderMap(r);renderChart();renderTiming(r);renderMiniMetrics();}
function projection([lon,lat]){return [(lon+14)/50*680,(64-lat)/30*330];}
function geoPath(geometry){const polygons=geometry.type==='Polygon'?[geometry.coordinates]:geometry.coordinates;return polygons.map(poly=>poly.map(ring=>ring.map((c,i)=>`${i?'L':'M'}${projection(c).map(v=>v.toFixed(1)).join(',')}`).join('')+'Z').join('')).join('');}
function mapColor(p){if(!Number.isFinite(p))return '#9eaa8d';const low=[145,169,121],high=[197,105,62];return `rgb(${low.map((c,i)=>Math.round(c+(high[i]-c)*p)).join(',')})`;}
function renderMap(record){$('#europe-map').setAttribute('viewBox',innerWidth<=650?'105 85 480 235':'0 0 680 330');const site=manifest.sites[state.site];$('#map-coordinate').textContent=`${site.lat.toFixed(2)}° N / ${Math.abs(site.lon).toFixed(2)}° ${site.lon<0?'W':'E'}`;const paths=geo.features.map(f=>`<path class="country-path ${['Morocco','Algeria','Tunisia'].includes(f.properties.name)?'context':''}" d="${geoPath(f.geometry)}"/>`).join('');let grid='';for(let lat=35;lat<=65;lat+=10){const [,y]=projection([0,lat]);grid+=`<line class="map-grid" x1="0" y1="${y}" x2="680" y2="${y}"/>`;}for(let lon=-10;lon<=40;lon+=10){const [x]=projection([lon,40]);grid+=`<line class="map-grid" x1="${x}" y1="0" x2="${x}" y2="330"/>`;}const markers=manifest.sites.map((s,i)=>{const [x,y]=projection([s.lon,s.lat]);const p=record.allProbabilities?.[i];const active=i===state.site;const dx=s.name==='London'?-12:12,dy=s.name==='Paris'?17:4;return `<g class="map-marker ${active?'selected':''}" data-site="${i}" transform="translate(${x},${y})" role="button" tabindex="0" aria-label="Select ${s.name}, ${Number.isFinite(p)?pct(p)+' event probability':'temperature outlook'}">${active?'<circle class="marker-ring" r="21"/><circle class="marker-ring" r="14" opacity=".4"/>':''}<circle class="marker-core" r="${active?7:5}" fill="${mapColor(p)}"/><text class="marker-label" x="${dx}" y="${dy}" text-anchor="${dx<0?'end':'start'}">${s.name}</text></g>`;}).join('');$('#europe-map').innerHTML=grid+paths+markers;$('.map-foot').innerHTML=record.allProbabilities?.some(Number.isFinite)?'<span><i class="legend-dot soft"></i>Lower event probability</span><div class="legend-gradient"></div><span><i class="legend-dot warm"></i>Higher</span>':'<span>Event probability unavailable · temperature outlook locations</span>';$('#map-selection').innerHTML=`<div>${escape(site.name)}<span>${state.source==='live'?'Live outlook':'Selected location'}</span></div><strong>${pct(record.probability)}</strong>`;$('#europe-map').querySelectorAll('[data-site]').forEach(g=>{const select=()=>{state.site=Number(g.dataset.site);render();};g.onclick=select;g.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select();}};});}
function chartData(){const start=addDays(state.date,-Math.floor(state.window/2));const rows=[];const d=data();const live=state.source==='live';let runIndex=-1;if(!live&&state.source==='issued')runIndex=d.runs.initializations.indexOf(addDays(state.date,-state.lead-1));for(let i=0;i<state.window;i++){const date=addDays(start,i);let observed=null,forecast=null;if(live)forecast=state.live.daily[date]?.[state.site]??null;else{const oi=d.observations.dates.indexOf(date);if(oi>=0)observed=d.observations.tmax[oi][state.site];if(runIndex>=0){const fi=d.runs.dates[runIndex].indexOf(date);if(fi>=0)forecast=d.runs.tmax[runIndex][fi][state.site];}}rows.push({date,observed,forecast,threshold:d.thresholdTable[calendarIndex(date)][state.site]});}return rows;}
function pathFor(rows,key,x,y){let open=false;return rows.map((r,i)=>{if(!Number.isFinite(r[key])){open=false;return '';}const command=open?'L':'M';open=true;return `${command}${x(i).toFixed(1)},${y(r[key]).toFixed(1)}`;}).join(' ');}
function renderChart(){const permitted=state.source==='research'?['observed','threshold']:state.source==='live'?['forecast','threshold']:['observed','forecast','threshold'];if(![...state.lines].some(k=>permitted.includes(k)))state.lines.add('threshold');chartRows=chartData();const svg=$('#temperature-chart');const W=Math.max(420,$('#chart-container').clientWidth),H=280,pad={l:42,r:18,t:34,b:37};svg.setAttribute('viewBox',`0 0 ${W} ${H}`);svg.style.aspectRatio=`${W}/${H}`;const vals=chartRows.flatMap(r=>[...state.lines].map(k=>r[k])).filter(Number.isFinite);const lo=Math.floor((Math.min(...vals)-2)/5)*5,hi=Math.ceil((Math.max(...vals)+2)/5)*5;const x=i=>pad.l+i/(chartRows.length-1)*(W-pad.l-pad.r),y=v=>pad.t+(hi-v)/(hi-lo)*(H-pad.t-pad.b);chartLayout={W,H,x,y};let html='';const targetIndex=chartRows.findIndex(r=>r.date===state.date);const half=(x(1)-x(0))/2;const first=state.task==='ongoing'?targetIndex-2:targetIndex,last=state.task==='ongoing'?targetIndex:targetIndex+2;html+=`<rect x="${x(Math.max(0,first))-half}" y="${pad.t}" width="${x(Math.min(chartRows.length-1,last))-x(Math.max(0,first))+2*half}" height="${H-pad.t-pad.b}" fill="#ecd9c7" opacity=".35"/><text x="${x(targetIndex)}" y="17" text-anchor="middle" class="chart-axis" style="fill:#b27b55;font-size:9px">TARGET ${state.task==='onset'?'ONSET':'EVENT DAY'}</text>`;for(let value=lo;value<=hi;value+=5)html+=`<line class="chart-grid" x1="${pad.l}" x2="${W-pad.r}" y1="${y(value)}" y2="${y(value)}"/><text class="chart-axis" x="${pad.l-11}" y="${y(value)+3}" text-anchor="end">${value}°</text>`;const tickStep=W<650?5:3;chartRows.forEach((r,i)=>{if(i%tickStep===0||i===chartRows.length-1)html+=`<text class="chart-axis" x="${x(i)}" y="${H-12}" text-anchor="middle">${fmtDate(r.date,{day:'numeric',month:'short'})}</text>`;});if(state.lines.has('threshold'))html+=`<path class="chart-threshold" d="${pathFor(chartRows,'threshold',x,y)}"/>`;if(state.lines.has('observed'))html+=`<path class="chart-actual" d="${pathFor(chartRows,'observed',x,y)}"/>`;if(state.lines.has('forecast'))html+=`<path class="chart-forecast" d="${pathFor(chartRows,'forecast',x,y)}"/>`;const r=selectedRecord();const issueDate=r.issue?.slice(0,10);const ii=chartRows.findIndex(row=>row.date===issueDate);if(ii>=0)html+=`<line x1="${x(ii)}" x2="${x(ii)}" y1="${pad.t}" y2="${H-pad.b}" stroke="#a7b59a" stroke-width="1" stroke-dasharray="3 4"/><text class="chart-axis" x="${x(ii)+5}" y="${H-pad.b-7}" style="font-size:8px">${state.source==='research'?'INPUT WINDOW ENDS':'ISSUE DATE'}</text>`;if(state.lines.has('observed')&&Number.isFinite(chartRows[targetIndex].observed))html+=`<circle cx="${x(targetIndex)}" cy="${y(chartRows[targetIndex].observed)}" r="4" fill="#32654d" stroke="#fffef9" stroke-width="2"/>`;if(state.lines.has('forecast')&&Number.isFinite(chartRows[targetIndex].forecast))html+=`<circle cx="${x(targetIndex)}" cy="${y(chartRows[targetIndex].forecast)}" r="4" fill="#ce8258" stroke="#fffef9" stroke-width="2"/>`;html+=`<line id="chart-crosshair" x1="0" x2="0" y1="${pad.t}" y2="${H-pad.b}" stroke="#a5af98" stroke-width="1" opacity="0"/>`;svg.innerHTML=html;svg.setAttribute('aria-label',`Temperature in ${manifest.sites[state.site].name}, target ${fmtDate(state.date)}. ${state.source==='research'?'Observed temperature context and local threshold.':'Forecast and local threshold; historical observations only where available.'} Use arrow keys to inspect dates.`);$('#chart-source').textContent=state.source==='issued'?'Observed: retrospective ERA5 verification · Forecast: one frozen GFS run · Shading: days required by the event rule':state.source==='research'?'Observed ERA5 temperatures provide historical context. The classifier predicts an event probability, not temperature.':`Latest GFS provider feed · Retrieved ${new Date(state.live.fetchedAt).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit',timeZone:'UTC'})} UTC · No future verification`;$('#chart-target').textContent=`Target: ${fmtDate(state.date,{day:'numeric',month:'short'})}`;$$('.chart-toggle').forEach(b=>{const allowed=!(b.dataset.line==='forecast'&&state.source==='research')&&!(b.dataset.line==='observed'&&state.source==='live');const active=allowed&&state.lines.has(b.dataset.line);b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));b.disabled=(b.dataset.line==='forecast'&&state.source==='research')||(b.dataset.line==='observed'&&state.source==='live');});$('#chart-tooltip').hidden=true;hoverIndex=null;svg.onpointermove=e=>{const rect=svg.getBoundingClientRect();const px=(e.clientX-rect.left)/rect.width*W;const i=Math.max(0,Math.min(chartRows.length-1,Math.round((px-pad.l)/(W-pad.l-pad.r)*(chartRows.length-1))));inspectChart(i);};svg.onpointerleave=()=>{hoverIndex=null;$('#chart-tooltip').hidden=true;$('#chart-crosshair')?.setAttribute('opacity','0');};svg.onkeydown=e=>{if(['ArrowRight','ArrowLeft'].includes(e.key)){e.preventDefault();inspectChart(Math.max(0,Math.min(chartRows.length-1,(hoverIndex??targetIndex)+(e.key==='ArrowRight'?1:-1))));}};}
function inspectChart(i){hoverIndex=i;const r=chartRows[i],tooltip=$('#chart-tooltip'),cx=chartLayout.x(i);$('#chart-crosshair').setAttribute('x1',cx);$('#chart-crosshair').setAttribute('x2',cx);$('#chart-crosshair').setAttribute('opacity','1');tooltip.innerHTML=`<strong>${fmtDate(r.date)}</strong>${['observed','forecast','threshold'].filter(k=>state.lines.has(k)&&Number.isFinite(r[k])).map(k=>`<span>${{observed:'Observed afterward',forecast:'GFS forecast',threshold:'Local hot threshold'}[k]}<b>${n(r[k],1)}°C</b></span>`).join('')}`;tooltip.hidden=false;tooltip.style.left=`${Math.max(80,Math.min($('#chart-container').clientWidth-80,cx/chartLayout.W*$('#chart-container').clientWidth))}px`;}
function renderTiming(r){let points,note;if(state.source==='issued'){points=[['Initialized',r.initialization.slice(0,10),'00:00 UTC'],['Warning issued',r.issue.slice(0,10),'00:00 UTC'],['Target day',state.date,`${state.lead*24}h after warning`]];note='Availability is assumed within 12h of initialization; the replay waits 24h before issuing. Historical delivery logs are unavailable.';}else if(state.source==='research'){points=[['Inputs end',r.issue.slice(0,10),'End of observed day'],['Target day',state.date,`${state.lead}-day forecast`],['Verified later',state.date,'ERA5 event label']];note='This experiment assumes end-of-day observations were available. ERA5 publication latency was not modeled.';}else{points=[['Feed retrieved',state.live.fetchedAt.slice(0,10),new Date(state.live.fetchedAt).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit',timeZone:'UTC'})+' UTC'],['Target day',state.date,'UTC daily maximum'],['Not yet verified',state.date,'Future observations absent']];note='Live mode uses the latest provider feed, which may combine model updates. It is not a frozen historical run or a verified warning.';}$('#timing-track').innerHTML=points.map(([label,date,small])=>`<div class="timing-point">${label}<strong>${fmtDate(date,{day:'numeric',month:'short'})}</strong><small>${small}</small></div>`).join('');$('#timing-note').textContent=note;}
function regionRows(method){const source=state.source==='live'?'issued':state.source;const rows=datasets[source].regions.filter(r=>r.experiment===expName()&&(source==='research'||r.method===(method||'joint_error_adjusted')));return manifest.sites.map(s=>rows.find(r=>r.site===s.name));}
function renderMiniMetrics(){const row=regionRows()[state.site];$('#performance-context').textContent=`${manifest.sites[state.site].name} · ${state.task==='onset'?'New onset':'Ongoing event'} · ${state.lead}-day lead · ${state.source==='research'?'2021–2025 held-out study':'2026 archived-warning test'}${state.source==='live'?' (historical reference only)':''}`;$('#mini-metrics').innerHTML=[['F1 score',row.f1],['Precision',row.precision],['Recall',row.recall]].map(([label,value])=>`<div class="mini-metric"><strong>${n(value)}</strong><span>${label}</span></div>`).join('');}
function renderAtlas(){const source=state.source==='research'?'research':'issued';const method=source==='issued'?state.atlasMethod:null;const rows=regionRows(method);const metric=state.metric;const values=rows.map(r=>r[metric]);const best=rows[values.indexOf(Math.max(...values))],worst=rows[values.indexOf(Math.min(...values))];const support=r=>r.positive_days??r.test_positive_days??0;const total=rows.reduce((a,r)=>a+support(r),0);$('#atlas-method-wrap').hidden=source==='research';$('#atlas-method').value=state.atlasMethod;$('#atlas-metric').value=metric;$('#atlas-context').textContent=`${state.task==='onset'?'New event onset':'Ongoing heatwave'} · ${state.lead}-day lead · ${source==='issued'?'8 July–30 September 2026 archived replay':'2021–2025 held-out climate study'}. Scores use the full test period, not the selected date.`;$('#atlas-cards').innerHTML=`<article class="atlas-stat"><span>Highest ${metric.toUpperCase()} score</span><strong>${best.site}</strong><p>${n(best[metric])} ${metric.toUpperCase()} · ${support(best)} observed event days</p></article><article class="atlas-stat"><span>Where the signal is weaker</span><strong>${worst.site}</strong><p>${n(worst[metric])} ${metric.toUpperCase()} · ${support(worst)} observed event days</p></article><article class="atlas-stat"><span>Evidence behind the comparison</span><strong>${total}</strong><p>Observed event location-days · all 7 locations retained</p></article>`;$('#regional-table').innerHTML=rows.map((r,i)=>`<tr data-site="${i}" class="${i===state.site?'selected-row':''}" tabindex="0" aria-label="Inspect ${r.site}"><td><strong>${escape(r.site)}</strong><small>${escape(manifest.sites[i].country)}</small></td><td class="score-cell">${n(r.f1)}<div class="score-bar ${r.f1<.5?'warm':''}"><span style="width:${r.f1*100}%"></span></div></td><td>${pct(r.precision)}</td><td>${pct(r.recall)}</td><td>${support(r)}</td><td><span class="signal-label ${r[metric]<.5?'limited':''}">${r[metric]<.5?'Limited skill':'Stronger signal'}</span></td></tr>`).join('');$('#regional-table').querySelectorAll('[data-site]').forEach(tr=>{const pick=()=>{state.site=Number(tr.dataset.site);setView('explorer');};tr.onclick=pick;tr.onkeydown=e=>{if(e.key==='Enter'){pick();}};});$('#atlas-footnote').textContent=state.source==='live'?'These are archived-study scores, not live-forecast verification. Live forecast outcomes have not been observed.':'Scores describe the sampled grid locations. Fewer observed events mean less evidence; these are not complete country-wide estimates. “Stronger signal” is a descriptive score label, not a significance test.';$('#lead-comparison').innerHTML=[1,3,7].map(lead=>{const e=datasets[source].report.experiments[`${state.task}_lead${lead}`];const score=source==='issued'?e.methods[state.atlasMethod].test:e.test;return `<div class="lead-stat"><span>${lead} day${lead>1?'s':''} ahead</span><strong>${n(score.f1)}</strong><small>Pooled F1 · ${pct(score.recall)} recall</small></div>`;}).join('');}
function liveRecord(){const bank=liveModel.banks[expName()],task=state.task,ofs=task==='ongoing'?[-2,-1,0]:[-1,0,1,2],month=Number(state.date.slice(5,7)),validatedSeason=manifest.live.validatedMonths.includes(month);const probs=manifest.sites.map((site,s)=>{if(!validatedSeason)return null;const values=ofs.map(o=>state.live.daily[addDays(state.date,o)]?.[s]);const thresholds=ofs.map(o=>liveModel.referenceTable[calendarIndex(addDays(state.date,o))][s]);if(!values.every(Number.isFinite))return null;return adjustedRisk(values,thresholds,bank.errors,s,task);});const p=probs[state.site];return {probability:p,predicted:Number.isFinite(p)?p>=bank.cutoff:null,truth:null,cutoff:bank.cutoff,allProbabilities:probs,issue:state.live.fetchedAt,validatedSeason};}
async function loadLive(force=false){$('#notice').hidden=false;$('#notice').textContent='Connecting to the live GFS weather feed…';$('#loading').hidden=false;$$('.view').forEach(v=>v.hidden=true);try{if(!force&&state.live&&Date.now()-Date.parse(state.live.fetchedAt)<600000){render();return;}if(liveRequest){await liveRequest;render();return;}liveRequest=(async()=>{const params=new URLSearchParams({latitude:manifest.sites.map(s=>s.gridLat).join(','),longitude:manifest.sites.map(s=>s.gridLon).join(','),hourly:'temperature_2m',models:'gfs_global',forecast_days:'10',past_days:'2',timezone:'GMT',elevation:manifest.sites.map(()=>'nan').join(','),cell_selection:'nearest'});const response=await fetch(`${manifest.live.endpoint}?${params}`,{signal:AbortSignal.timeout(45000)});if(!response.ok)throw Error(`Provider returned HTTP ${response.status}.`);const payload=await response.json();const records=Array.isArray(payload)?payload:[payload];if(records.length!==manifest.sites.length)throw Error('The live feed returned an incomplete set of locations.');const daily={};records.forEach((record,s)=>{if(record.utc_offset_seconds!==0||record.hourly_units.temperature_2m!=='°C')throw Error('Unexpected live feed units or timezone.');const grouped={};record.hourly.time.forEach((time,i)=>{const day=time.slice(0,10);(grouped[day]??=[]).push(record.hourly.temperature_2m[i]);});for(const [day,values] of Object.entries(grouped)){if(!daily[day])daily[day]=Array(manifest.sites.length).fill(null);if(values.length===24&&values.every(Number.isFinite))daily[day][s]=Math.fround(Math.max(...values));}});state.live={daily,fetchedAt:new Date().toISOString()};})();await liveRequest;if(state.source!=='live')return;state.notice='Live weather feed · Future outcomes are not verified. The probability adjustment is experimental and was developed on early-summer 2026 archived runs.';if(!manifest.live.validatedMonths.includes(Number(state.date.slice(5,7))))state.notice='Live weather feed · This target is outside May–September, the validated study period. Temperatures are available; an event probability is not published.';render();}catch(error){if(state.source!=='live')return;$('#loading').hidden=true;$('#error-state').hidden=false;$('#error-message').textContent=`Live feed unavailable: ${error.message} Archived model results remain available in the other tabs.`;state.notice='The live provider feed could not be retrieved. No replacement weather values are displayed.';$('#notice').textContent=state.notice;$('#notice').hidden=false;}finally{liveRequest=null;}}
function explain(){const r=selectedRecord();const e=state.source==='live'?'LIVE MODEL SCOPE':state.source==='issued'?'INSIDE THE WARNING':'INSIDE THE CLIMATE MODEL';const details=state.source==='issued'?'<p>The displayed probability is the fraction of forecast trajectories satisfying the event rule after adding <strong>joint forecast errors from the development period only</strong>. Error vectors are sampled together across event days.</p><p>This is an empirical error adjustment, not an ensemble of independent weather-model runs. The cutoff was selected before the test period. It does not define a public safety category.</p>':state.source==='research'?'<p>This is an actual saved probability from the trained <strong>gradient-boosting model</strong>, using only historical observations at or before the input date. The features and cutoff were selected on validation data.</p><p>The original experiment assumes recent ERA5 observations were available; it does not demonstrate real-time warning delivery.</p>':'<p>The live temperature chart uses the <strong>latest GFS provider feed</strong>. It may combine updates and differs from the frozen-run research design.</p><p>During May–September, the earlier joint-error model can produce an experimental estimate. Outside that period the UI intentionally shows temperatures without a model probability. Future outcomes are unavailable.</p>';dialog(e,state.source==='live'?'A live outlook, with its limits.':'How to read this signal.',details+`<div class="dialog-kv"><span>Event definition</span><strong>${state.task==='onset'?'First day of a 3-day hot run':'Third or later hot day'}</strong></div><div class="dialog-kv"><span>Study cutoff</span><strong>${pct(r.cutoff)}</strong></div><div class="dialog-kv"><span>Selected lead</span><strong>${state.lead} day${state.lead>1?'s':''}</strong></div>`);}
function exportForecast(){const r=selectedRecord(),site=manifest.sites[state.site];const row={source:state.source,site:site.name,target_date:state.date,lead_days:state.lead,event_type:state.task,probability:r.probability,classification_cutoff:r.cutoff,predicted_event:r.predicted,observed_era5_outcome:r.truth,issue_time:r.issue,initialization:r.initialization||'',verification:state.source==='live'?'Not yet observed':'Retrospective ERA5',source_mode:state.source==='live'?'Experimental live feed':'Historical experiment'};const quote=v=>`"${String(v??'').replace(/"/g,'""')}"`;const text=Object.keys(row).join(',')+'\n'+Object.values(row).map(quote).join(',')+'\n';const url=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`heatcast-${site.id}-${state.date}-${state.lead}d-${state.task}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);showToast('Forecast exported with its source, timing, and verification status.');}
function bind(){document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#sidebar').classList.remove('open');$('#menu-button').setAttribute('aria-expanded','false');}});document.addEventListener('click',e=>{if($('#sidebar').classList.contains('open')&&!e.target.closest('#sidebar')&&!e.target.closest('#menu-button')){$('#sidebar').classList.remove('open');$('#menu-button').setAttribute('aria-expanded','false');}}); $$('.nav-item[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));$$('[data-go]').forEach(b=>b.onclick=()=>setView(b.dataset.go));$('.brand').onclick=e=>{e.preventDefault();setView('explorer');};$$('.source-tab[data-source]').forEach(b=>b.onclick=()=>setSource(b.dataset.source));$('#location').onchange=e=>{state.site=Number(e.target.value);render();};$('#event-type').onchange=e=>{state.task=e.target.value;render();};$$('[data-lead]').forEach(b=>b.onclick=()=>{state.lead=Number(b.dataset.lead);if(state.source==='live')state.date=validDates()[0];render();});$('#target-date').onchange=e=>setDate(e.target.value||state.date);$('#previous-day').onclick=e=>{e.preventDefault();const d=validDates(),i=d.indexOf(state.date);if(i>0)setDate(d[i-1]);};$('#next-day').onclick=e=>{e.preventDefault();const d=validDates(),i=d.indexOf(state.date);if(i<d.length-1)setDate(d[i+1]);};$$('.chart-toggle').forEach(b=>b.onclick=()=>{const key=b.dataset.line;if(state.lines.has(key)&&state.lines.size===1){showToast('Keep at least one chart series visible.');return;}state.lines.has(key)?state.lines.delete(key):state.lines.add(key);renderChart();});$('#chart-window').onchange=e=>{state.window=Number(e.target.value);renderChart();};$('#atlas-metric').onchange=e=>{state.metric=e.target.value;renderAtlas();};$('#atlas-method').onchange=e=>{state.atlasMethod=e.target.value;renderAtlas();};$('#menu-button').onclick=()=>{const open=$('#sidebar').classList.toggle('open');$('#menu-button').setAttribute('aria-expanded',String(open));};$('#guide-button').onclick=()=>setView('research');$('#info-button').onclick=()=>dialog('HEATCAST OBSERVATORY','A changing climate.<br>A clearer perspective.','<p>An interactive research interface connected to actual saved HeatCast model outputs and published weather archives.</p><p>Use the forecast explorer to inspect a single prediction, the regional atlas to examine model weaknesses, and the research guide to understand how the evidence was produced.</p><p>ERA5 / Copernicus · NOAA GFS · Open-Meteo. Map geometry: Natural Earth.</p>');$('#explain-button').onclick=explain;$('#source-info').onclick=()=>state.source==='live'?dialog('LIVE PROVIDER FEED','Current weather, clearly labelled.','<p>The live feed is requested from Open-Meteo with the GFS model explicitly selected. Data are timestamped when received. Future verification is unavailable.</p><p>Summer error adjustments remain experimental. Outside the validated May–September period, only temperature outlooks are displayed.</p><button id="refresh-live" class="primary-button">Refresh live feed</button>'):dialog('KNOW YOUR DATA',state.source==='issued'?'An archived warning replay.':'A historical climate experiment.',state.source==='issued'?'<p><strong>2026 GFS archive:</strong> target dates July 8–September 30. A previous-day 00 UTC run supplies every event day. Warnings are issued with a conservative publication buffer and verified afterward against ERA5.</p><p>The initial dataset contains 150 requested runs. One missing run excludes three development targets; all 85 test target dates remain complete.</p>':'<p><strong>2021–2025 held-out results:</strong> gradient boosting trained on 1981–2016 observations and selected on 2017–2020. The UI displays the saved predictions and actual ERA5 verification.</p><p>The model observes recent historical weather. ERA5 delivery delay is not part of this older experimental design.</p>');$('#dialog-content').addEventListener('click',e=>{if(e.target.id==='refresh-live'){$('#detail-dialog').close();loadLive(true);}});$('.dialog-close').onclick=()=>$('#detail-dialog').close();$('.dialog-done').onclick=()=>$('#detail-dialog').close();$('#detail-dialog').onclick=e=>{if(e.target===$('#detail-dialog')){const r=$('#detail-dialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#detail-dialog').close();}};$('#export-button').onclick=()=>{if(state.view==='research'){const a=document.createElement('a');a.href='reports/manuscript.md';a.download='heatcast-manuscript.md';a.click();}else if(state.view==='atlas'){const source=state.source==='research'?'research':'issued';const a=document.createElement('a');a.href=`reports/${source}-comparison.csv`;a.download=`heatcast-${source}-comparison.csv`;a.click();}else exportForecast();};$('#retry-button').onclick=()=>state.source==='live'?loadLive(true):location.reload();let timer;window.onresize=()=>{clearTimeout(timer);timer=setTimeout(()=>{if(manifest&&state.view==='explorer'&&(state.source!=='live'||state.live)){renderChart();renderMap(selectedRecord());}},120);};}
async function init(){try{const responses=await Promise.all(['data/manifest.json','data/issued.json','data/research.json','data/live-model.json','assets/europe.geojson'].map(async url=>{const r=await fetch(url);if(!r.ok)throw Error(`Missing data asset: ${url}`);return r.json();}));[manifest,datasets.issued,datasets.research,liveModel,geo]=responses;$('#location').innerHTML=manifest.sites.map((site,i)=>`<option value="${i}">${site.name}, ${site.country}</option>`).join('');const q=new URLSearchParams(location.search);if(['issued','research','live'].includes(q.get('source')))state.source=q.get('source');const site=manifest.sites.findIndex(s=>s.id===q.get('site'));if(site>=0)state.site=site;if([1,3,7].includes(Number(q.get('lead'))))state.lead=Number(q.get('lead'));if(['ongoing','onset'].includes(q.get('event')))state.task=q.get('event');if(['explorer','atlas','research'].includes(location.hash.slice(1)))state.view=location.hash.slice(1);if(q.get('date'))state.date=q.get('date');const dates=validDates();if(!dates.includes(state.date))state.date=state.source==='research'?'2025-08-12':dates[0];bind();if(state.source==='live'){renderControls();await loadLive();}else render();}catch(error){$('#loading').hidden=true;$('#error-state').hidden=false;$('#error-message').textContent=error.message;$('#retry-button').onclick=()=>location.reload();}}
init();
